#!/usr/bin/env node

/**
 * Reproducibly vendor the browser-safe Sucrase transform used by QuickJS.
 *
 * The package graph and build tool are pinned in package-lock.json. The build
 * emits the minified bundle, a machine-readable provenance manifest, and the
 * complete license text for every package whose code esbuild included.
 *
 * Usage:
 *   npm ci
 *   npm run sucrase:build
 *   npm run sucrase:check
 */

import { createHash } from 'node:crypto';
import { access, mkdir, readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import path from 'node:path';
import { build, version as esbuildVersion } from 'esbuild';

const checkOnly = process.argv.slice(2).includes('--check');
const unexpectedArgs = process.argv.slice(2).filter((arg) => arg !== '--check');
if (unexpectedArgs.length > 0) {
  throw new Error(`Unknown arguments: ${unexpectedArgs.join(', ')}`);
}

const scriptDir = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(scriptDir, '..');
const packageJsonPath = path.join(root, 'package.json');
const packageLockPath = path.join(root, 'package-lock.json');
const packageJson = JSON.parse(await readFile(packageJsonPath, 'utf8'));
const sucraseVersion = exactVersion(packageJson.devDependencies.sucrase, 'sucrase');
const expectedEsbuildVersion = exactVersion(
  packageJson.devDependencies.esbuild,
  'esbuild',
);
if (esbuildVersion !== expectedEsbuildVersion) {
  throw new Error(
    `esbuild version drift: expected ${expectedEsbuildVersion}, found ${esbuildVersion}`,
  );
}

const entrySource = [
  "import { transform } from 'sucrase';",
  'globalThis.sucraseTransform = transform;',
  '',
].join('\n');
const bundleRelative = 'backend/utils/sucrase_bundle.js';
const provenanceRelative = 'backend/utils/sucrase_bundle.provenance.json';
const licensesRelative = 'backend/utils/sucrase_bundle.LICENSES.txt';
const banner = [
  '/*!',
  ` * Sucrase ${sucraseVersion} browser bundle for NoClick.`,
  ' * Copyright (c) 2012-2018 various contributors; MIT License.',
  ` * Rebuild with npm run sucrase:build. See ${licensesRelative}.`,
  ' */',
].join('\n');
const buildOptions = {
  bundle: true,
  charset: 'utf8',
  format: 'iife',
  legalComments: 'none',
  minify: true,
  platform: 'browser',
  target: ['es2020'],
  treeShaking: true,
};

const result = await build({
  ...buildOptions,
  absWorkingDir: root,
  banner: { js: banner },
  logLevel: 'silent',
  metafile: true,
  outfile: path.join(root, bundleRelative),
  stdin: {
    contents: entrySource,
    loader: 'js',
    resolveDir: root,
    sourcefile: 'scripts/sucrase_bundle_entry.js',
  },
  write: false,
});
if (result.outputFiles.length !== 1) {
  throw new Error(`Expected one esbuild output, found ${result.outputFiles.length}`);
}
const bundle = result.outputFiles[0].contents;
const bundleSha256 = sha256(bundle);
const packageLockSha256 = sha256(await readFile(packageLockPath));

const packageNames = new Set();
for (const inputPath of Object.keys(result.metafile.inputs)) {
  const packageName = packageNameFromInput(inputPath);
  if (packageName) packageNames.add(packageName);
}
const bundledPackages = [];
const licenseSections = [];
for (const packageName of [...packageNames].sort()) {
  const packageRoot = path.join(root, 'node_modules', ...packageName.split('/'));
  const metadata = JSON.parse(
    await readFile(path.join(packageRoot, 'package.json'), 'utf8'),
  );
  const licensePath = await findLicense(packageRoot);
  const licenseText = normalizeNewlines(await readFile(licensePath, 'utf8')).trim();
  const repository = repositoryUrl(metadata.repository);
  bundledPackages.push({
    name: metadata.name,
    version: metadata.version,
    license: metadata.license,
    repository,
  });
  licenseSections.push(
    [
      `===== ${metadata.name}@${metadata.version} (${metadata.license}) =====`,
      repository ? `Source: ${repository}` : '',
      '',
      licenseText,
      '',
    ]
      .filter((line, index) => line || index !== 1)
      .join('\n'),
  );
}
const sucrase = bundledPackages.find((item) => item.name === 'sucrase');
if (!sucrase || sucrase.version !== sucraseVersion || sucrase.license !== 'MIT') {
  throw new Error(
    `Sucrase package drift: expected sucrase@${sucraseVersion} under MIT`,
  );
}

const provenance = `${JSON.stringify(
  {
    schemaVersion: 1,
    artifact: bundleRelative,
    sha256: bundleSha256,
    entrySourceSha256: sha256(Buffer.from(entrySource)),
    packageLockSha256,
    buildTool: { name: 'esbuild', version: esbuildVersion },
    buildOptions,
    bundledPackages,
  },
  null,
  2,
)}\n`;
const licenses = [
  'Sucrase browser bundle: third-party license texts',
  '==================================================',
  '',
  'This file is generated by scripts/build-sucrase-bundle.mjs from the exact',
  'package versions recorded in package-lock.json.',
  '',
  ...licenseSections,
].join('\n');

await mkdir(path.join(root, 'backend', 'utils'), { recursive: true });
await writeOrVerify(bundleRelative, bundle);
await writeOrVerify(provenanceRelative, Buffer.from(provenance));
await writeOrVerify(licensesRelative, Buffer.from(licenses));
console.log(
  `${checkOnly ? 'Verified' : 'Built'} Sucrase ${sucraseVersion} bundle ` +
    `${bundleSha256} with ${bundledPackages.length} bundled package notices.`,
);

function exactVersion(specifier, packageName) {
  if (!/^[0-9]+\.[0-9]+\.[0-9]+$/.test(specifier || '')) {
    throw new Error(`${packageName} must use an exact version in package.json`);
  }
  return specifier;
}

function sha256(content) {
  return createHash('sha256').update(content).digest('hex');
}

function packageNameFromInput(inputPath) {
  const marker = 'node_modules/';
  const markerIndex = inputPath.lastIndexOf(marker);
  if (markerIndex === -1) return null;
  const parts = inputPath.slice(markerIndex + marker.length).split('/');
  return parts[0].startsWith('@') ? `${parts[0]}/${parts[1]}` : parts[0];
}

async function findLicense(packageRoot) {
  for (const filename of [
    'LICENSE',
    'LICENSE.md',
    'LICENSE.txt',
    'LICENCE',
    'COPYING',
  ]) {
    const candidate = path.join(packageRoot, filename);
    try {
      await access(candidate);
      return candidate;
    } catch {
      // Try the next conventional filename.
    }
  }
  throw new Error(`Bundled package has no license file: ${packageRoot}`);
}

function repositoryUrl(repository) {
  if (!repository) return '';
  return typeof repository === 'string' ? repository : repository.url || '';
}

function normalizeNewlines(value) {
  return value.replaceAll('\r\n', '\n').replaceAll('\r', '\n');
}

async function writeOrVerify(relativePath, expected) {
  const destination = path.join(root, relativePath);
  if (checkOnly) {
    let actual;
    try {
      actual = await readFile(destination);
    } catch {
      throw new Error(`Generated artifact is missing: ${relativePath}`);
    }
    if (!actual.equals(expected)) {
      throw new Error(
        `Generated artifact is stale: ${relativePath}; run npm run sucrase:build`,
      );
    }
  } else {
    await writeFile(destination, expected);
  }
}
